from glom import *
import glom.core as core

# Debug version
def _t_eval_debug(target, _t, scope):
    t_path = core._T_PATHS[_t]
    print(f'Path: {t_path}')
    i = 1
    if t_path[0] is core.T:
        cur = target
    elif t_path[0] is core.S:
        cur = scope
    else:
        raise ValueError('TType instance with invalid root object')
    path_stack = [target]
    while i < len(t_path):
        op, arg = t_path[i], t_path[i + 1]
        if type(arg) in (core.Spec, core.TType, core.Literal):
            arg = scope[glom](target, arg, scope)
        print(f'Processing op={op!r}, arg={arg!r}, cur={cur!r}, stack={path_stack}')
        if op == '.':
            try:
                cur = getattr(cur, arg)
                path_stack.append(cur)
            except AttributeError as e:
                raise core.PathAccessError(e, core.Path(_t), i // 2)
        elif op == '[':
            if arg is core.UP:
                if len(path_stack) > 1:
                    path_stack.pop()
                    cur = path_stack[-1]
            else:
                try:
                    cur = cur[arg]
                    path_stack.append(cur)
                except (KeyError, IndexError, TypeError):
                    pass
        elif op == 'P':
            get = scope[core.TargetRegistry].get_handler('get', cur, path=t_path[2:i+2:2])
            try:
                cur = get(cur, arg)
                path_stack.append(cur)
            except Exception as e:
                raise core.PathAccessError(e, core.Path(_t), i // 2)
        elif op == '(':
            args, kwargs = arg
            scope[core.Path] += t_path[2:i+2:2]
            cur = scope[glom](target, core.Call(cur, args, kwargs), scope)
            path_stack.append(cur)
        i += 2
    print(f'Result: {cur!r}')
    return cur

# Monkey-patch
core._t_eval = _t_eval_debug
print(glom([[1]], T[0][0][0][UP]))
